// Parse JSON dari Gemini (TEXT: caption + hashtags + image_prompt), lalu bikin image_url.
let out = {};
try {
  const content = $json.candidates[0].content.parts[0].text;
  out = JSON.parse(content);
} catch (e) {
  out = { caption: 'Gagal parse output AI', hashtags: '', image_prompt: 'modern tropical architecture, professional photography' };
}
const prompt = out.image_prompt || 'modern tropical architecture, professional photography';
// --- IMAGE: Pollinations.ai (gratis). Seed acak biar gambar fresh + ngurangin masalah antrian/cache. ---
const seed = Math.floor(Math.random() * 1000000);
const imageUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}?width=1024&height=1024&nologo=true&seed=${seed}`;
return [{ json: {
  caption: out.caption || '',
  hashtags: out.hashtags || '',
  image_prompt: prompt,
  image_url: imageUrl
} }];
